static int mod=998244353;

	public static void main(String[] args)throws IOException {
		PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
		BufferedReader bf=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer(bf.readLine());
		int n=Integer.parseInt(st.nextToken());
		long k=Long.parseLong(st.nextToken());
		if(k>n) {
			out.println(0);
			out.close();
			System.exit(0);
		}
		int a=n-(int)k;
		long ncr=1;
		long ans=0;
		for(int i=a;i>0;i--) {
			long sgn=(a-i)%2==0?1:-1;
			ans+=sgn*ncr*fexp(i,n);
			ans%=mod;
			ans=(ans+mod)%mod;
			ncr=(ncr*i+mod)%mod;
			ncr=(ncr*fexp(a-i+1,mod-2)+mod)%mod;
		}
		a=Math.max(a, (int)k);
		for(int i=a+1;i<=n;i++) {
			ans=(ans*i+mod)%mod;
		}
		for(int i=1;i<=n-a;i++) {
			ans=(ans*fexp(i,mod-2)+mod)%mod;
		}
		if(k!=0) {
			ans*=2;
			ans%=mod;
		}
		out.println(ans);
		out.close();
	}
	public static long fexp(long a,long e)
	{
		if(e==0) return 1;
		long tmp = fexp(a,e/2);
		tmp = (tmp*((long)tmp))%mod;
		if(e%2==1) tmp = (tmp*((long)a))%mod;
		return tmp;
	}
